function capText(s, n) {
  return s && s.length > n ? s.slice(0, n - 1) + "…" : s || "";
}
function mkChoice(title, question, options, answer) {
  return {
    type: "interactive",
    kind: "choice",
    title,
    reason: "Pilih satu jawaban yang paling tepat.",
    question,
    options,
    answer
  };
}
function mkClassify(title, instruction, map) {
  return {
    type: "interactive",
    kind: "classify",
    title,
    reason: instruction,
    choices: [...new Set(Object.values(map))],
    items: Object.keys(map),
    answer: map
  };
}
function mkSequence(title, instruction, steps) {
  return {
    type: "interactive",
    kind: "sequence",
    title,
    reason: instruction,
    steps,
    answer: [...steps]
  };
}
function mkChecklist(title, reason, items) {
  return {
    type: "interactive",
    kind: "checklist",
    title,
    reason,
    items
  };
}
function mkExplain(title, question, keywords) {
  return {
    type: "interactive",
    kind: "explain",
    title,
    reason: "Tulis jawaban singkat dengan contoh atau alasan. Ini melatih pemahaman, bukan sekadar memilih.",
    question,
    keywords
  };
}
